import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("a vendor that was sent back can be edited again", { tag: "@LIF-09" }, async ({ factory, apiAs }) => {
    // Arrange: a vendor in review whose contract extraction a reviewer rejected, so the vendor is rejected
    const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
    const reviewer = await apiAs("reviewer");
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );
    const member = await apiAs("member");
    const newName = uniqueName("Renamed Vendor");

    // Act
    const response = await member.patch(`/api/vendors/${vendor.id}`, { data: { name: newName } });

    // Assert
    const body = await expectStatus(response, 200);
    expect(body.name).toBe(newName);
    const stored = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.name).toBe(newName);
  });
});
